import {KEY,seed,valid,read,save,parse} from './model.mjs';
const $=id=>document.getElementById(id);let state,blocked=false,installPrompt,undoTasks=null;
const clone=x=>structuredClone(x);
function status(message,error=false){$('status').textContent=message;$('status').className=error?'error':'';}
function composer(){return {text:$('text').value,category:$('category').value};}
function change(tasks,{undo=true,message='✓ Guardado en este navegador'}={}){if(blocked)return false;try{const previous=clone(state.tasks);state=save(localStorage,{revision:state.revision+1,tasks,composer:composer()},state);if(undo)undoTasks=previous;status(message);render();return true;}catch(e){status('No se ha guardado el cambio. '+e.message,true);render();return false;}}
function render(){const done=state.tasks.filter(t=>t.done).length;$('summary').textContent=`${state.tasks.length-done} tareas pendientes · ${done} completadas`;$('lists').replaceChildren();for(const [cat,title] of [['particular','🏠 Particular'],['trabajo','💼 Trabajo']]){const list=document.createElement('section');list.className='list';const h=document.createElement('h2');h.textContent=title;const tasks=state.tasks.filter(t=>t.category===cat);const badge=document.createElement('span');badge.className='badge';badge.textContent=tasks.length;h.append(badge);list.append(h);for(const t of tasks){const row=document.createElement('label');row.className='row'+(t.done?' done':'');const input=document.createElement('input');input.type='checkbox';input.checked=t.done;input.disabled=blocked;input.addEventListener('change',()=>change(state.tasks.map(x=>x.id===t.id?{...x,done:input.checked}:x)));const span=document.createElement('span');span.textContent=t.text;row.append(input,span);list.append(row);}if(!tasks.length){const p=document.createElement('p');p.className='empty';p.textContent='No hay tareas pendientes.';list.append(p);}$('lists').append(list);}$('undo').disabled=!undoTasks||blocked;$('clear').disabled=!done||blocked;$('add').querySelector('button').disabled=blocked;$('text').disabled=blocked;$('category').disabled=blocked;$('import').disabled=blocked;$('draft-info').textContent=$('text').value.trim()?'Texto sin añadir. Se conserva como borrador al escribir.':'Marcar y desmarcar guarda el cambio al instante.';}
try{state=read(localStorage);if(localStorage.getItem(KEY)===null)state=save(localStorage,{...state,revision:state.revision+1},state);$('text').value=state.composer.text;$('category').value=state.composer.category;status(state.composer.text?'Lista y borrador recuperados':'✓ Lista recuperada · guardado automático');}catch(e){state=seed();state.tasks=[];blocked=true;status('No se pudo abrir el almacenamiento. '+e.message+' No se sobrescribirán los datos.',true);}render();
function saveDraft(){change(state.tasks,{undo:false,message:$('text').value.trim()?'Borrador guardado · pulsa «Añadir» para incorporarlo':'✓ Guardado en este navegador'});}
$('text').addEventListener('input',saveDraft);$('category').addEventListener('change',saveDraft);
$('add').addEventListener('submit',e=>{e.preventDefault();if(blocked)return;const additions=parse($('text').value,$('category').value);if(!additions.length)return;const text=$('text').value;$('text').value='';if(change([...state.tasks,...additions],{message:'✓ Tareas añadidas y guardadas'})){$('text').focus();}else{$('text').value=text;render();}});
$('undo').addEventListener('click',()=>{if(!undoTasks)return;const previous=undoTasks;if(change(clone(previous),{undo:false,message:'✓ Último cambio deshecho y guardado'})){undoTasks=null;render();}});
$('clear').addEventListener('click',()=>change(state.tasks.filter(t=>!t.done),{message:'✓ Completadas retiradas. Puedes recuperar el último cambio con «Deshacer».'}));
$('export').addEventListener('click',()=>{try{const payload=blocked?{format:'mis-notas-recovery',saved:localStorage.getItem(KEY)}:{format:'mis-notas-backup-v1',state:{...state,composer:composer()}};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='mis-notas-copia.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}catch{status('No se pudo exportar la copia.',true);}});
$('import').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;const data=JSON.parse(await file.text());if(data.format!=='mis-notas-backup-v1'||!valid(data.state))throw Error('El archivo no es una copia válida de Mis notas.');if(!confirm('¿Restaurar esta copia sustituyendo la lista actual? Puedes deshacer la sustitución mientras mantengas abierta esta pantalla.'))return;const oldComposer=composer();$('text').value=data.state.composer.text;$('category').value=data.state.composer.category;if(!change(clone(data.state.tasks),{message:'✓ Copia restaurada y guardada'})){$('text').value=oldComposer.text;$('category').value=oldComposer.category;render();}}catch(err){status(err.message,true);}e.target.value='';});
addEventListener('storage',e=>{if(e.key===KEY||e.key===null){blocked=true;status('La lista cambió en otra pestaña. Recarga esta pantalla para usar la última versión. Puedes exportar primero el texto que tengas escrito.',true);render();}});
addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false;});$('install').addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true;}});addEventListener('appinstalled',()=>{$('install').hidden=true;});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>status('La lista funciona, pero no se ha preparado el acceso sin conexión.',true));
